#!/usr/bin/env node
/**
 * Builds the note editor's WebView document (mobile/editor-web) into one
 * self-contained HTML string at editor-web/build/editorHtml.js, which
 * NoteRichEditor passes to TenTap as `customSource`.
 *
 * This is TenTap's "advanced setup": the stock bundle only knows
 * TenTapStartKit, and the [[wikilink]] chips need a ProseMirror plugin inside
 * the WebView. Rerun after changing anything under editor-web/ or a module it
 * imports (wikilinks.ts, wikilinkBridgeProtocol.ts), and commit the output;
 * Metro bundles the generated file, not the sources.
 *
 * Usage: node scripts/build-editor-web.mjs
 */
import { readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "vite";

const mobileDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const root = join(mobileDir, "editor-web");
const outDir = join(root, "build");
const distDir = join(root, ".dist");

await build({
	root,
	configFile: false,
	logLevel: "warn",
	base: "./",
	resolve: {
		// TenTap's web build instead of its React Native entry.
		alias: [{ find: /^@10play\/tentap-editor$/, replacement: "@10play/tentap-editor/web" }],
	},
	esbuild: { jsx: "automatic" },
	// Keep mobile's NativeWind PostCSS config out of the WebView build.
	css: { postcss: { plugins: [] } },
	define: { "process.env.NODE_ENV": JSON.stringify("production") },
	build: {
		outDir: distDir,
		emptyOutDir: true,
		assetsInlineLimit: Number.MAX_SAFE_INTEGER,
		cssCodeSplit: false,
		modulePreload: false,
		rollupOptions: { output: { inlineDynamicImports: true } },
	},
});

// Inline the single JS chunk (and any CSS) so the WebView needs no file access,
// the same shape as TenTap's own editorHtml.js.
const assetsDir = join(distDir, "assets");
let html = readFileSync(join(distDir, "index.html"), "utf8");
for (const file of readdirSync(assetsDir)) {
	const body = readFileSync(join(assetsDir, file), "utf8");
	if (file.endsWith(".js")) {
		const tag = new RegExp(`<script type="module" crossorigin src="\\./assets/${file.replace(/\./g, "\\.")}"></script>`);
		if (!tag.test(html)) throw new Error(`No script tag for ${file}`);
		// A function replacer: the bundle contains `$&`-style sequences.
		html = html.replace(tag, () => `<script type="module">\n${body.replace(/<\/script/gi, "<\\/script")}\n</script>`);
	} else if (file.endsWith(".css")) {
		const tag = new RegExp(`<link rel="stylesheet" crossorigin href="\\./assets/${file.replace(/\./g, "\\.")}">`);
		html = html.replace(tag, () => `<style>\n${body}\n</style>`);
	}
}
if (/src="\.\/assets\/|href="\.\/assets\//.test(html)) throw new Error("An asset was left un-inlined");
rmSync(distDir, { recursive: true, force: true });

writeFileSync(
	join(outDir, "editorHtml.js"),
	`// @ts-nocheck\n/* eslint-disable */\n// Generated by scripts/build-editor-web.mjs - do not edit.\nexport const editorHtml = ${JSON.stringify(html)};\n`
);
writeFileSync(join(outDir, "editorHtml.d.ts"), "export declare const editorHtml: string;\n");
console.log(`Built editor-web/build/editorHtml.js (${(html.length / 1024).toFixed(0)} KB)`);
